import boto3

def vision_client():
    return boto3.client('rekognition')

def normalize_labels(labels):
    return [label['Name'] for label in labels]

def normalize_text(text_detections):
    return ' '.join([block['Text'] for block in text_detections if block['BlockType'] == 'LINE'])

def normalize_safety_score(moderation_labels):
    return sum([label['Confidence'] for label in moderation_labels]) / len(moderation_labels) if moderation_labels else 0
